import {invoiceDateIssue} from './invoice-dates.js';
import {extractFile,parseExtractedText,parseBaselineText} from './extraction.js';
import {validateExtractionReview} from './extraction-validation.js';
import {arithmeticChecks} from './arithmetic.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function extractAndReview(file,kind,progress){const {text,layout}=await extractFile(file,progress,{detailed:true,kind}),data=parseExtractedText(text,kind,layout);data.baselineExtraction=parseBaselineText(text,kind);return reviewExisting(data,text,file);}
export function reviewExisting(data,text,file=null){
 if(data.additionalInvoices?.length){
  const ranges=[data.firstInvoicePages,...data.additionalInvoices].map(({firstPage,lastPage})=>firstPage===lastPage?String(firstPage):`${firstPage}–${lastPage}`).join(', ');
  throw Error(`This file contains multiple invoices. Split it by page range (${ranges}) and upload each invoice separately.`);
 }
 const kind=data.type;return new Promise(resolve=>{
 const dialog=document.createElement('dialog');dialog.className='ocr-dialog';const url=file?URL.createObjectURL(file):null;
 const evidence=(key)=>{const f=data.extraction?.fields?.[key];return f?`<small class="field-risk ${f.support==='supported'?'supported':'uncertain'}">${esc(f.support)} · ${esc(f.reason)}</small>${f.evidence.length?`<button type="button" class="text-button" data-evidence="${esc(key)}">Show source evidence</button>`:''}`:'';};
 dialog.innerHTML=`<div class="dialog-top"><div><span class="eyebrow">VERIFY EXTRACTED DETAILS</span><h2>Review ${kind==='invoice'?'invoice':'purchase order'}</h2><p>Support labels are heuristic signals, not calibrated probabilities. Start with the highlighted fields. Leave unreadable values blank; you can finish them in the inbox. Confirmation never authorizes payment.</p></div><button type="button" class="icon-button" data-cancel aria-label="Cancel extraction">×</button></div><div class="ocr-grid"><section><h3>Original document</h3>${!file?`<pre>${esc(text)}</pre>`:/\.pdf$/i.test(file.name)?`<iframe title="Original PDF" src="${url}"></iframe>`:`<img alt="Uploaded document" src="${url}">`}<div class="source-evidence" aria-live="polite">Select “Show source evidence” to highlight the extracted source passage.</div><details><summary>Extracted text</summary><pre>${esc(text)}</pre></details>${data.baselineExtraction?`<details><summary>Baseline parser comparison</summary><p>Original regex parser using the same PDF.js / Tesseract text; no probability or accuracy claim.</p><pre>${esc(JSON.stringify(data.baselineExtraction,null,2))}</pre></details>`:''}</section><form><div class="ocr-fields">${[['vendor','Vendor'],...(kind==='invoice'?[['customer','Customer (billed to)']]:[]),['supplierId','Supplier identifier (optional)'],['number','Document number'],['poNumber','PO reference'],['currency','Currency'],['date','Invoice date (YYYY-MM-DD)'],['due','Due date (YYYY-MM-DD)'],['subtotal',data.taxInclusive?'Net subtotal (before tax)':'Displayed subtotal'],['shipping','Shipping / freight'],['discount','Discount'],['taxRate','Document-wide tax rate (%)'],['tax','Displayed tax'],['total','Displayed total']].map(([k,l])=>`<label>${l}<input name="${k}" value="${esc(data[k])}"  ${['subtotal','shipping','discount','taxRate','tax','total'].includes(k)?'type="number" min="0" step="any"':''}>${evidence(k)}</label>`).join('')}</div><div class="date-review" aria-live="polite"></div><h3>Line items</h3><p>Keep printed amounts separate from quantity × price. Blank optional amounts remain unknown. Match verified SKUs on both documents.</p><div class="ocr-lines"></div><button type="button" class="text-button" data-add>+ Add line item</button><div class="arithmetic-review" aria-live="polite"></div><label class="review-confirm"><input type="checkbox" required> I checked these fields and line items against the original document. Any remaining contradictions must stay on hold.</label><p class="ocr-error" role="alert"></p><button class="button primary" type="submit">Save extraction & continue</button></form></div>`;document.body.append(dialog);
 const lineHost=dialog.querySelector('.ocr-lines');let rowIndex=0;
 function addLine(l={}){const index=rowIndex++;const row=document.createElement('div');row.className='ocr-line';row.innerHTML=[['sku','SKU','text'],['description','Description','text'],['quantity',l.ratePercent!=null?'Percentage basis':'Quantity','number'],...(l.ratePercent!=null?[['ratePercent','Rate (%)','number']]:[['unitPrice','Unit price','number']]),['amount','Printed amount','number']].map(([k,label,type])=>`<label>${label}<input data-key="${k}" type="${type}" ${type==='number'?`min="${k==='quantity'?0.001:0}" step="${k==='quantity'?'.001':'any'}"`:''} value="${esc(l[k])}" >${evidence(`lines.${index}.${k}`)}</label>`).join('')+'<button type="button" class="text-button danger" data-remove aria-label="Remove line">Remove</button>';row.querySelector('[data-remove]').onclick=()=>{row.remove();renderChecks();};lineHost.append(row);}
 data.lines.forEach(addLine);dialog.querySelector('[data-add]').onclick=()=>{addLine();renderChecks();};
 function read(){const form=new FormData(dialog.querySelector('form'));const d={...data};for(const k of ['vendor','customer','supplierId','number','poNumber','currency','date','due'])d[k]=String(form.get(k)||'').trim();for(const k of ['subtotal','shipping','discount','taxRate','tax','total'])d[k]=form.get(k)===''?null:Number(form.get(k));d.lines=[...lineHost.children].map(row=>Object.fromEntries([...row.querySelectorAll('input')].map(i=>[i.dataset.key,['quantity','unitPrice','ratePercent','amount'].includes(i.dataset.key)?(i.value===''?null:Number(i.value)):i.value.trim()])));return d;}
 function renderChecks(){
  const current = read();
  const dateIssue = kind === 'invoice' ? invoiceDateIssue(current.date, current.due) : '';
  const dateReview = dialog.querySelector('.date-review');
  dateReview.classList.toggle('check', Boolean(dateIssue));
  dateReview.textContent = dateIssue;
  dateReview.hidden = !dateIssue;
  const checks=arithmeticChecks(current);dialog.querySelector('.arithmetic-review').innerHTML=checks.length?'<h3>Arithmetic contradictions — hold for resolution</h3>'+checks.map(c=>`<p class="check">${esc(c.message)}</p>`).join(''):'<p>Available arithmetic checks agree. Missing displayed values still need source review.</p>';}
 dialog.addEventListener('input',e=>{if(e.target.type==='checkbox')return;dialog.querySelector('input[type=checkbox]').checked=false;renderChecks();});
 dialog.addEventListener('click',e=>{const button=e.target.closest('[data-evidence]');if(!button)return;const f=data.extraction.fields[button.dataset.evidence];dialog.querySelector('.source-evidence').innerHTML=`<h3>${esc(button.dataset.evidence)} · source evidence</h3>${f.evidence.map(v=>`<p>Page ${v.page}, text row ${v.row} (${esc(v.method)})</p><mark>${esc(v.text)}</mark>`).join('')}`;});
 function close(value){dialog.close();dialog.remove();if(url)URL.revokeObjectURL(url);resolve(value);}dialog.querySelector('[data-cancel]').onclick=()=>close(null);dialog.oncancel=e=>{e.preventDefault();close(null);};dialog.querySelector('form').onsubmit=e=>{e.preventDefault();try{const d=read();validateExtractionReview(d);d.arithmetic=arithmeticChecks(d);d.sourceText=text;d.sourceFilename=file?.name||'inbox-source.txt';d.extractionReviewed=true;d.extractionReview={confirmedAt:new Date().toISOString(),originalValues:data.extraction?.fields||{},reviewedValues:{vendor:d.vendor,customer:d.customer,number:d.number,poNumber:d.poNumber,currency:d.currency,date:d.date,due:d.due,subtotal:d.subtotal,shipping:d.shipping,discount:d.discount,taxRate:d.taxRate,tax:d.tax,total:d.total,lines:d.lines},remainingContradictions:d.arithmetic};close(d);}catch(err){dialog.querySelector('.ocr-error').textContent=err.message;}};renderChecks();dialog.showModal();});}
